package com.yeyamo_mobile.api.referral_service.infrastructure.web;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.referral_service.domain.ReferralException;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(ReferralException.class)ResponseEntity<Problem>referral(ReferralException e){HttpStatus status=e.code().contains("NOT_FOUND")?HttpStatus.NOT_FOUND:e.code().contains("FORBIDDEN")||e.code().equals("NOT_CODE_OWNER")?HttpStatus.FORBIDDEN:HttpStatus.CONFLICT;return response(status,e.code(),e.getMessage());}@ExceptionHandler(NoSuchElementException.class)ResponseEntity<Problem>missing(Exception e){return response(HttpStatus.NOT_FOUND,"REFERRAL_NOT_FOUND",e.getMessage());}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class})ResponseEntity<Problem>bad(Exception e){return response(HttpStatus.BAD_REQUEST,"REFERRAL_INVALID",e.getMessage());}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<Problem>validation(MethodArgumentNotValidException e){String detail=e.getBindingResult().getFieldErrors().stream().findFirst().map(f->f.getField()+" "+f.getDefaultMessage()).orElse("Invalid request");return response(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR",detail);}private ResponseEntity<Problem>response(HttpStatus s,String c,String d){return ResponseEntity.status(s).body(new Problem(c,d,Instant.now()));}record Problem(String code,String detail,Instant timestamp){}}
